const lockSearchFeedPublication = `-- name: LockSearchFeedPublication :one
SELECT feed, published_run_revision, published_at FROM catalog_search_feed_publications WHERE feed=$1 FOR UPDATE
`

// Publication protocol: begin a READ COMMITTED transaction, run
// LockSearchFeedPublication, then PublishFeedMembership as a separate statement,
// then commit. The separate statement gets a fresh snapshot after any prior
// publisher commits. Acquiring this lock inside the publication CTE is unsafe:
// its pre-wait snapshot can miss the previous publisher's new membership rows.
func (q *Queries) LockSearchFeedPublication(ctx context.Context, feed string) (CatalogSearchFeedPublication, error) {
	row := q.db.QueryRow(ctx, lockSearchFeedPublication, feed)
	var i CatalogSearchFeedPublication
	err := row.Scan(&i.Feed, &i.PublishedRunRevision, &i.PublishedAt)
	return i, err
}

