const reserveCatalogBudget = `-- name: ReserveCatalogBudget :one
INSERT INTO catalog_budget_reservations(kind,hour_at,reservations,used)
SELECT $1,$2,jsonb_build_object($3::text,true),1
WHERE $4::integer BETWEEN 1 AND 100000
    AND char_length($3::text) BETWEEN 1 AND 128
ON CONFLICT(kind,hour_at) DO UPDATE SET
    reservations=catalog_budget_reservations.reservations||EXCLUDED.reservations,
    used=catalog_budget_reservations.used+CASE WHEN catalog_budget_reservations.reservations ? $3::text THEN 0 ELSE 1 END
WHERE catalog_budget_reservations.reservations ? $3::text
    OR catalog_budget_reservations.used<$4::integer
RETURNING kind, hour_at, reservations, used
`

type ReserveCatalogBudgetParams struct {
	Kind         string             `json:"kind"`
	HourAt       pgtype.Timestamptz `json:"hour_at"`
	IdentityHash string             `json:"identity_hash"`
	BudgetLimit  int32              `json:"budget_limit"`
}

// Atomic UPSERT locks the UTC-hour bucket across app instances, including retries
// of an already charged identity. A full bucket returns no row without charging.
func (q *Queries) ReserveCatalogBudget(ctx context.Context, arg ReserveCatalogBudgetParams) (CatalogBudgetReservation, error) {
	row := q.db.QueryRow(ctx, reserveCatalogBudget,
		arg.Kind,
		arg.HourAt,
		arg.IdentityHash,
		arg.BudgetLimit,
	)
	var i CatalogBudgetReservation
	err := row.Scan(
		&i.Kind,
		&i.HourAt,
		&i.Reservations,
		&i.Used,
	)
	return i, err
}

